CREATE TABLE IF NOT EXISTS service_outbox (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,table_name VARCHAR(64) NOT NULL,aggregate_key VARCHAR(160) NOT NULL,deleted BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),published_at DATETIME(3),claimed_until DATETIME(3),INDEX ix_outbox_pending(published_at,claimed_until,id));
CREATE TABLE IF NOT EXISTS integration_applied (source_name VARCHAR(30) NOT NULL,table_name VARCHAR(64) NOT NULL,aggregate_key VARCHAR(160) NOT NULL,last_version BIGINT NOT NULL DEFAULT -1,PRIMARY KEY(source_name,table_name,aggregate_key));
DROP TRIGGER IF EXISTS `ix_orders_insert`;
CREATE TRIGGER `ix_orders_insert` AFTER INSERT ON `orders` FOR EACH ROW INSERT INTO service_outbox(table_name,aggregate_key,deleted) VALUES('notification_orders',CONCAT_WS(':',NEW.`id`),0);
DROP TRIGGER IF EXISTS `ix_orders_update`;
CREATE TRIGGER `ix_orders_update` AFTER UPDATE ON `orders` FOR EACH ROW INSERT INTO service_outbox(table_name,aggregate_key,deleted) VALUES('notification_orders',CONCAT_WS(':',NEW.`id`),0);
DROP TRIGGER IF EXISTS `ix_orders_delete`;
CREATE TRIGGER `ix_orders_delete` AFTER DELETE ON `orders` FOR EACH ROW INSERT INTO service_outbox(table_name,aggregate_key,deleted) VALUES('notification_orders',CONCAT_WS(':',OLD.`id`),1);
DROP TRIGGER IF EXISTS ix_order_items_insert;
CREATE TRIGGER ix_order_items_insert AFTER INSERT ON order_items FOR EACH ROW INSERT INTO service_outbox(table_name,aggregate_key) VALUES('notification_orders',NEW.order_id);
DROP TRIGGER IF EXISTS ix_order_items_update;
CREATE TRIGGER ix_order_items_update AFTER UPDATE ON order_items FOR EACH ROW INSERT INTO service_outbox(table_name,aggregate_key) VALUES('notification_orders',NEW.order_id);
DROP TRIGGER IF EXISTS ix_order_items_delete;
CREATE TRIGGER ix_order_items_delete AFTER DELETE ON order_items FOR EACH ROW INSERT INTO service_outbox(table_name,aggregate_key) VALUES('notification_orders',OLD.order_id);
CREATE TABLE IF NOT EXISTS `ref_auth_users` (`id` bigint unsigned NOT NULL,`email` varchar(255) NULL,`phone` varchar(20) NULL,`full_name` varchar(120) NULL,`avatar_url` varchar(500) NULL,`status` enum('ACTIVE','LOCKED','DELETED') NULL,`created_at` datetime(3) NULL,`deleted_at` datetime(3) NULL,PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `ref_auth_roles` (`id` tinyint unsigned NOT NULL,`code` varchar(30) NULL,`name` varchar(60) NULL,PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `ref_auth_user_roles` (`user_id` bigint unsigned NOT NULL,`role_id` tinyint unsigned NOT NULL,PRIMARY KEY(`user_id`,`role_id`));
CREATE TABLE IF NOT EXISTS `ref_product_products` (`id` bigint unsigned NOT NULL,`shop_id` bigint unsigned NULL,`category_id` bigint unsigned NULL,`brand_id` bigint unsigned NULL,`name` varchar(255) NULL,`slug` varchar(280) NULL,`short_description` varchar(500) NULL,`description` text NULL,`thumbnail_url` varchar(500) NULL,`currency` char(3) NULL,`min_price` decimal(12,2) NULL,`max_price` decimal(12,2) NULL,`original_price` decimal(12,2) NULL,`discount_percent` tinyint unsigned NULL,`promo_label` varchar(60) NULL,`attributes` json NULL,`weight_grams` int unsigned NULL,`has_free_return_30d` tinyint(1) NULL,`has_buyer_protection` tinyint(1) NULL,`is_best_deal` tinyint(1) NULL,`supports_ship_to_store` tinyint(1) NULL,`rating_avg` decimal(3,2) NULL,`rating_count` int unsigned NULL,`sold_count` int unsigned NULL,`view_count` int unsigned NULL,`favorite_count` int unsigned NULL,`status` enum('DRAFT','ACTIVE','HIDDEN','BANNED') NULL,`version` bigint NULL,`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,`deleted_at` datetime(3) NULL,PRIMARY KEY(`id`),INDEX (`shop_id`));
CREATE TABLE IF NOT EXISTS `ref_product_product_skus` (`id` bigint unsigned NOT NULL,`product_id` bigint unsigned NULL,`sku_code` varchar(64) NULL,`name` varchar(255) NULL,`price` decimal(12,2) NULL,`original_price` decimal(12,2) NULL,`stock_quantity` int unsigned NULL,`sold_count` int unsigned NULL,`status` enum('ACTIVE','INACTIVE') NULL,`version` bigint NULL,`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,`deleted_at` datetime(3) NULL,PRIMARY KEY(`id`),INDEX (`product_id`));
CREATE TABLE IF NOT EXISTS `ref_product_shops` (`id` bigint unsigned NOT NULL,`owner_user_id` bigint unsigned NULL,`name` varchar(150) NULL,`slug` varchar(170) NULL,`logo_url` varchar(500) NULL,`banner_url` varchar(500) NULL,`description` text NULL,`province` varchar(100) NULL,`is_authorized` tinyint(1) NULL,`rating_avg` decimal(3,2) NULL,`rating_count` int unsigned NULL,`follower_count` int unsigned NULL,`status` enum('PENDING','ACTIVE','SUSPENDED') NULL,`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,`deleted_at` datetime(3) NULL,PRIMARY KEY(`id`),INDEX (`owner_user_id`));
CREATE TABLE IF NOT EXISTS `ref_product_reviews` (`id` bigint unsigned NOT NULL,`product_id` bigint unsigned NULL,`sku_id` bigint unsigned NULL,`user_id` bigint unsigned NULL,`order_id` bigint unsigned NULL,`order_item_id` bigint unsigned NULL,`reviewer_name` varchar(120) NULL,`reviewer_avatar_url` varchar(500) NULL,`rating` tinyint unsigned NULL,`sentiment` enum('BAD','NEUTRAL','GOOD') NULL,`content` text NULL,`is_anonymous` tinyint(1) NULL,`status` enum('VISIBLE','HIDDEN','PENDING') NULL,`like_count` int unsigned NULL,`seller_reply` text NULL,`seller_replied_at` datetime(3) NULL,`created_at` datetime(3) NULL,`updated_at` datetime(3) NULL,`deleted_at` datetime(3) NULL,PRIMARY KEY(`id`),INDEX (`product_id`),INDEX (`user_id`));

CREATE TABLE IF NOT EXISTS integration_bootstrap(source_key VARCHAR(100) PRIMARY KEY,completed_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
